// Entry point: global styles, database, offline support and a tiny router.
import './style.css';
import { db } from './db.js';
import { registerSW } from 'virtual:pwa-register';

// Register the service worker (generated by vite-plugin-pwa at build time).
// It caches the app so it keeps working offline.
registerSW({ immediate: true });

// --- Pages -------------------------------------------------------------
// For now every page is a placeholder. Each future feature will live in
// its own module under src/pages/ and export a render(container) function.
const routes = {
  '/':         { title: 'Dashboard',   render: placeholder('Riepilogo del giorno e della settimana.') },
  '/timer':    { title: 'Timer round', render: placeholder('Round, pause e preset (es. Kumite 3x2min).') },
  '/workouts': { title: 'Allenamenti', render: placeholder('Registro sessioni con stima kcal (MET).') },
  '/diet':     { title: 'Dieta',       render: placeholder('Pasti, kcal e macro del giorno.') },
  '/weight':   { title: 'Peso',        render: placeholder('Peso reale vs peso stimato dal bilancio.') },
  '/profile':  { title: 'Profilo',     render: placeholder('Dati personali, BMR, TDEE e obiettivo.') },
};

function placeholder(text) {
  return (container) => {
    container.innerHTML = `
      <section class="card">
        <p>${text}</p>
        <p class="muted">In costruzione.</p>
      </section>`;
  };
}

// --- Router ------------------------------------------------------------
// The part after '#' in the URL decides which page to show.
// Hash routing needs no server configuration, so it works on GitHub Pages
// and offline.
function router() {
  const path = location.hash.slice(1) || '/';
  const route = routes[path] ?? routes['/'];

  document.getElementById('page-title').textContent = route.title;
  route.render(document.getElementById('app'));

  // Highlight the active tab
  document.querySelectorAll('.tabbar a').forEach((a) => {
    a.classList.toggle('active', a.dataset.route === path);
  });
}

window.addEventListener('hashchange', router);
router();

// Quick sanity check that IndexedDB opens (visible in the browser console)
db.open()
  .then(() => console.log('[db] ready, version', db.verno))
  .catch((err) => console.error('[db] failed to open', err));
